// Recibe palabras clave del vehículo (marca, modelo, etc.) y las busca dentro de attributes JSONB.
// El campo attributes contiene strings como: 'MITSUBISHI,L200,4p Pickup,2024-,Normal Roof,...'
const raw = $input.first().json || {};
const keywords = (raw.keywords || raw.query || '').trim();
const brand = (raw.brand || '').trim();
const model = (raw.model || '').trim();
const year  = parseInt(raw.year, 10) || null;

// Construye patrón ILIKE combinado. Ejemplo: '%MITSUBISHI%MONTERO%' o '%MITSUBISHI%' si solo brand
let pattern = '';
if (brand && model) pattern = `%${brand}%${model}%`;
else if (brand) pattern = `%${brand}%`;
else if (keywords) pattern = `%${keywords.split(/\s+/).join('%')}%`;
else pattern = '%';

return [{ json: { pattern, brand, model, year, keywords } }];

const rows = $input.all().map(i => i.json);
const input = $('Build Pattern').first().json;
if (!rows.length) {
  return [{ json: { found: false, message: `Sin matches en attributes para pattern '${input.pattern}'.`, query: input } }];
}

// Intenta extraer años de la cadena CarroN dentro de attributes
function extractCompat(attrs, brand, model) {
  if (!attrs || typeof attrs !== 'object') return null;
  const entries = Object.values(attrs).filter(v => typeof v === 'string');
  const matched = entries.filter(s => {
    const up = s.toUpperCase();
    if (brand && !up.includes(brand.toUpperCase())) return false;
    if (model && !up.includes(model.toUpperCase())) return false;
    return brand || model;
  });
  return matched.length ? matched : null;
}

return [{ json: {
  found: true,
  count: rows.length,
  query: input,
  results: rows.map(r => ({
    sku: r.product_sku,
    title: r.title,
    brand: r.brand,
    category: r.category,
    price: r.price_amount ? `${r.price_amount} ${r.currency || 'USD'}` : 'consultar',
    stock: r.stock_status,
    promo: r.promo_text || null,
    matched_compat: extractCompat(r.attributes, input.brand, input.model)
  }))
} }];
